/**
 * Finds which beat starts the bar from how much the harmony changes from one beat to the next.
 *
 * `beat` is the beat being heard, counted along the grid, with the `sum` of its chroma over `hops` hops so far; `last`
 * is the previous beat's average chroma. `changes` holds how much the harmony changed on each beat of the grid's bar so
 * far, by its place in the bar, and `votes` which beat each recent bar pointed at, if any, newest last. `missed` is the
 * beat on which the accented beat first went missing, while it hasn't held since. `accent` is what the lights play.
 */
case class Downbeat(
  beat: Long,
  sum: Vector[Double],
  hops: Int,
  last: Option[Vector[Double]],
  changes: Map[Int, Double],
  votes: Vector[Option[Int]],
  missed: Option[Long],
  accent: BarAccent
) {

  /**
   * Moves on to `beats` beats into the grid, having just heard `chroma`, with the lights playing `lead` beats ahead of
   * what's heard. At each bar line of the grid the bar votes, and the accent is decided.
   */
  def at(beats: Double, chroma: Vector[Double], lead: Double): Downbeat = ???
}

object Downbeat {

  /** Bars of votes kept. */
  val Window: Int = 8

  /** Of a full `Window` of bars, how many must point at one beat to switch the accent on. */
  val OnVotes: Int = 7

  /** Bars in a row that must point at another beat before the accent moves there. */
  val MoveBars: Int = 4

  /** The accented beat holds again once it has at least `HeldVotes` of the last `MoveBars` bars. */
  val HeldVotes: Int = 3

  /** Bars from the first one that missed the accented beat until the accent is off, if it hasn't held since. */
  val OffBars: Int = 8

  /** A bar votes only when its biggest change is at least this, so a harmony that never changes doesn't. */
  val MinChange: Double = 0.1

  /** ...and beats the bar's next biggest by this much, so a harmony that changes as much on every beat doesn't. */
  val Margin: Double = 0.1

  /** A fresh search, accent off, at `beats` beats into the grid. */
  def start(beats: Double): Downbeat = ???

  /** How much the harmony changed between two chromas: 1 - their cosine similarity; 0 if either is empty. */
  def change(before: Vector[Double], after: Vector[Double]): Double = ???

  /** The place in the bar (0 to 3) whose change stands out from the bar's `changes`, if one does; None unless all four were heard. */
  def vote(changes: Map[Int, Double]): Option[Int] = ???

  /** The first beat on `slot`'s bar line (counted beat mod 4 = `slot`) strictly after `after` beats. */
  def landing(slot: Int, after: Double): Long = ???

  /**
   * `missed` and the accent after the grid's bar line at beat `line`, given the latest `votes`, newest last, with the
   * lights at `ahead` beats. No decision while a change is still to land; an off, once decided, is final.
   */
  def decide(votes: Vector[Option[Int]], missed: Option[Long], accent: BarAccent, line: Long, ahead: Double): (Option[Long], BarAccent) = ???
}

package beat

import scala.concurrent.duration.*

/**
 * Listens to live audio. Each hop of audio becomes one onset-strength value. A few times a second the tracker
 * tries every candidate beat grid over the last few seconds of onsets and keeps the one whose beats land on the
 * strongest onsets: that grid gives both the tempo and where the beats fall. Through quiet or unclear passages it
 * keeps the last confident beat for `holdSeconds`. Alongside the beat it follows the loudness and treble of the
 * music, picks out big hits and treble sparkles, and finds where the bar starts from the harmony (`downbeat`).
 */
case class BeatTracker(
  settings: TrackerSettings,
  detector: OnsetDetector,
  envelope: Vector[Double],
  loudness: Vector[Double],
  frames: Long,
  beat: Option[BeatState],
  bass: Vector[Double] = Vector.empty,
  recent: Vector[BeatState] = Vector.empty,
  surges: Vector[Double] = Vector.empty,
  treble: Vector[Double] = Vector.empty,
  levels: Levels = Levels(),
  hit: Option[Hit] = None,
  sparkle: Option[Hit] = None,
  sparkles: Long = 0,
  groove: Option[Groove] = None,
  news: Vector[TempoNews] = Vector.empty,
  pending: Option[BeatTracker.Pending] = None,
  downbeat: Option[Downbeat] = None
) {

  def reading: AudioReading =
    AudioReading(beat, levels.energy, levels.treble, hit, sparkle, sparkles, levels.pitch, groove.fold(Vector.empty)(_.lights), news,
      groove.flatMap(_.rhythmEnergy), downbeat.fold(BarAccent.Off)(_.accent))

  def step(frame: AudioFrame): BeatTracker = {
    val s = settings
    val now = frame.capturedAt
    val (nextDetector, onset) = detector.step(frame.samples)
    val nextEnvelope = (envelope :+ onset.flux).takeRight(s.capacity)
    val nextBass = (bass :+ onset.bassFlux).takeRight(s.capacity)
    val nextLoudness = (loudness :+ onset.rms).takeRight(s.capacity)
    val n = frames + 1

    // A tempo that stays put is evidence in itself: real songs often score well under `minConfidence` while the tempo
    // doesn't budge. So the tracker locks on to a confident estimate, or to a few seconds of estimates that agree;
    // once locked, a weaker estimate that agrees on the tempo keeps the beat.
    val estimate =
      if (n % s.reestimateEvery != 0 || nextEnvelope.size < s.minFrames) None
      else BeatTracker.estimate(s, nextEnvelope, nextBass, nextLoudness, now, beat)
    val estimated = estimate.map(_.state)
    val nextRecent = if (n % s.reestimateEvery != 0) recent else (recent ++ estimated).takeRight(s.steadyEstimates)
    val steady = BeatTracker.steady(nextRecent, s)
    val accepted =
      estimated.filter(e =>
        e.confidence >= s.minConfidence || steady || (e.confidence >= s.keepConfidence && beat.exists(BeatTracker.sameTempo(_, e)))
      )
    val (BeatTracker.Held(nextBeat, nextPending, _), news) =
      if (n % s.reestimateEvery != 0) (BeatTracker.Held(beat, pending, None), Vector.empty)
      else if (nextEnvelope.size < s.minFrames) (BeatTracker.Held(None, None, None), Vector.empty)
      else BeatTracker.decide(s, beat, pending, estimate, accepted, now)

    // Treble-led onsets are hi-hats and cymbals rather than the click of a kick, whose bass outweighs its treble.
    val trebleLed = onset.trebleFlux > BeatTracker.TrebleLed * onset.flux
    val background = BeatTracker.median(treble)
    val trebleExcess = if (trebleLed) math.max(0.0, onset.trebleFlux - 2 * background) else 0.0
    val nextLevels = levels.update(onset, trebleExcess, s)

    // Big hits and sparkles only count once a few seconds of music have set the bar. A big hit is a surge in
    // loudness over anything in those seconds: a crash or a drop lifts it for a while, a kick only for a moment.
    val settled = nextLoudness.size >= s.hitWindow && nextLoudness.takeRight(s.hitWindow).forall(_ >= s.silenceRms)
    val nextHit =
      BeatTracker.standsOut(nextLevels.loudFast, surges, s.hitRatio * surges.maxOption.getOrElse(0.0), hit, now, 400.millis)
        .filter(_ => settled)
        .orElse(hit)
    val newSparkle = BeatTracker
      .standsOut(onset.trebleFlux, treble, s.sparkleRatio * background, sparkle, now, 100.millis)
      .filter(_ => settled && trebleLed)

    // The kick pattern and the bar's first beat are found along the beat grid; a new lock starts both afresh, since its
    // beats are counted afresh.
    val nextGroove = nextBeat.map { b =>
      groove.filter(_ => beat.isDefined).fold(Groove.start(b.countAt(now)))(_.at(b.countAt(now), onset.kick, nextLevels.energy, s.rhythm, b.bpm))
    }
    val nextDownbeat = nextBeat.map { b =>
      val count = b.countAt(now)
      downbeat.filter(_ => beat.isDefined).fold(Downbeat.start(count))(_.at(count, onset.chroma, s.leadMs * b.bpm / 60000.0))
    }

    copy(
      detector = nextDetector,
      envelope = nextEnvelope,
      bass = nextBass,
      recent = nextRecent,
      loudness = nextLoudness,
      frames = n,
      beat = nextBeat,
      surges = (surges :+ nextLevels.loudFast).takeRight(s.hitWindow),
      treble = (treble :+ onset.trebleFlux).takeRight(s.sparkleWindow),
      levels = nextLevels,
      hit = nextHit,
      sparkle = newSparkle.orElse(sparkle),
      sparkles = if (newSparkle.isDefined) sparkles + 1 else sparkles,
      groove = nextGroove,
      news = news,
      pending = nextPending,
      downbeat = nextDownbeat
    )
  }
}

object BeatTracker {

  /** A kick's treble onset is well under its bass-weighted one; a hi-hat's is close to it or above. */
  val TrebleLed: Double = 0.65

  def initial(settings: TrackerSettings = TrackerSettings()): BeatTracker =
    BeatTracker(settings, OnsetDetector.initial(settings.window), Vector.empty, Vector.empty, 0L, None)

  /** Tempos within this fraction of each other count as the same, measured slightly differently. */
  val TempoTolerance: Double = 0.04

  /** Tempo ratios, such as 4:3 and 3:2, that a kick and other accents can sit at; half and double aren't among them. */
  private val RelatedRatios: Vector[Double] = Vector(2.0 / 3, 3.0 / 4, 4.0 / 3, 3.0 / 2)

  /** How many times better than the all-onset winner a related tempo must score on the kick to replace it. */
  private val KickMargin: Double = 1.1

  /** How close to a tempo ratio, relative to the ratio, a tempo must be to count as related. */
  val RelatedTolerance: Double = 0.02

  private val RelatedTempoRatios: Vector[Double] = Vector(1.0 / 2, 2.0 / 3, 3.0 / 4, 4.0 / 3, 3.0 / 2, 2.0)

  /** Whether `bpm` sits at one of the ratios 1:2, 2:3, 3:4, 4:3, 3:2 and 2:1 of the `locked` tempo. */
  def related(locked: Double, bpm: Double): Boolean =
    RelatedTempoRatios.exists(r => math.abs(bpm / locked - r) / r < RelatedTolerance)

  def sameTempo(a: BeatState, b: BeatState): Boolean = sameBpm(a.bpm, b.bpm)

  private def sameBpm(a: Double, b: Double): Boolean = math.abs(b - a) / a < TempoTolerance

  /**
   * The beat to report for an estimate: the accepted one, or the old beat while it is within `holdSeconds`. A tempo
   * related to the locked one waits out its hold first. Also the news, if the kick moved the tempo or a hold ended.
   */
  def decide(
    s: TrackerSettings,
    beat: Option[BeatState],
    pending: Option[Pending],
    estimate: Option[Estimate],
    accepted: Option[BeatState],
    now: FiniteDuration
  ): (Held, Vector[TempoNews]) = {
    val held = beat.filter(h => (now - h.updatedAt).toNanos / 1e9 <= s.holdSeconds)
    val result = accepted
      .flatMap(e => beat.map(hold(_, e, pending, now, s)))
      .getOrElse(Held(accepted.orElse(held), None, None))
    val followed = result.followedFrom.toVector.flatMap(from => result.beat.map(b => TempoNews.FollowedRelated(from, b.bpm)))
    val kickMoved = for {
      e <- estimate.toVector if result.followedFrom.isEmpty
      winner <- e.movedFrom
      kept <- result.beat if accepted.contains(kept)
      if !beat.exists(sameTempo(_, kept))
    } yield TempoNews.KickMoved(winner, kept.bpm)
    (result, followed ++ kickMoved)
  }

  /** A related tempo waiting out its hold, and when the estimates first agreed on it. */
  case class Pending(bpm: Double, since: FiniteDuration)

  /** The beat to report, the tempo still waiting, and the locked tempo that was left when the hold ended. */
  case class Held(beat: Option[BeatState], pending: Option[Pending], followedFrom: Option[Double])

  /**
   * A tempo related to the `locked` one has to be estimated steadily for `historySeconds` before it replaces the
   * lock, which stays as it was meanwhile. Returns the beat, the tempo waiting with the time it was first seen,
   * and the tempo left when the hold ended.
   */
  def hold(
    locked: BeatState,
    e: BeatState,
    pending: Option[Pending],
    now: FiniteDuration,
    s: TrackerSettings
  ): Held =
    if (sameTempo(locked, e) || !related(locked.bpm, e.bpm)) Held(Some(e), None, None)
    else {
      val since = pending.collect { case Pending(bpm, at) if sameBpm(bpm, e.bpm) => at }.getOrElse(now)
      if ((now - since).toNanos / 1e9 < s.historySeconds) Held(Some(locked.copy(updatedAt = now)), Some(Pending(e.bpm, since)), None)
      else Held(Some(e), None, Some(locked.bpm))
    }

  /** Whether the last `steadySeconds` of estimates all agree on the tempo, and are typically at least `keepConfidence`. */
  def steady(recent: Vector[BeatState], s: TrackerSettings): Boolean =
    recent.size >= s.steadyEstimates && {
      val middle = recent.sortBy(_.bpm).apply(recent.size / 2)
      recent.forall(sameTempo(middle, _)) && median(recent.map(_.confidence)) >= s.keepConfidence
    }

  def median(values: Vector[Double]): Double =
    if (values.isEmpty) 0.0 else values.sorted.apply(values.size / 2)

  /**
   * A new hit when `value` clears `bar`, and the previous one is at least `gap` ago. Its strength grows with how
   * far over the bar it is: just over is 0.5, twice the bar or more is 1.
   */
  def standsOut(
    value: Double,
    history: Vector[Double],
    bar: Double,
    previous: Option[Hit],
    now: FiniteDuration,
    gap: FiniteDuration
  ): Option[Hit] = {
    val clear = previous.forall(p => now - p.at >= gap)
    Option.when(history.nonEmpty && bar > 1e-9 && value > bar && clear)(Hit(now, math.min(1.0, 0.5 * value / bar)))
  }

  /** Tempos near 120 BPM are more likely than very slow or very fast ones; this breaks ties between multiples. */
  private def prior(bpm: Double): Double = {
    val octaves = math.log(bpm / 120.0) / math.log(2)
    math.exp(-0.5 * octaves * octaves)
  }

  private def interpolate(e: Array[Double], index: Double): Double = {
    val i = math.floor(index).toInt
    val t = index - i
    if (i < 0 || i + 1 >= e.length) 0.0 else e(i) * (1 - t) + e(i + 1) * t
  }

  private def smoothed(values: Vector[Double]): Array[Double] = {
    val raw = values.toArray
    Array.tabulate(raw.length)(i => 0.25 * raw(math.max(0, i - 1)) + 0.5 * raw(i) + 0.25 * raw(math.min(raw.length - 1, i + 1)))
  }

  /** Average onset strength on a beat grid with this period that ends `offset` frames before the latest frame. */
  private def gridMean(env: Array[Double], period: Double, offset: Double): (Double, Int) = {
    var sum = 0.0
    var k = 0
    var position = env.length - 1 - offset
    while (position >= 0) {
      sum += interpolate(env, position)
      k += 1
      position -= period
    }
    (if (k == 0) 0.0 else sum / k, k)
  }

  private def bestOffset(env: Array[Double], period: Double): (Double, Double, Int) = {
    val offsets = Iterator.iterate(0.0)(_ + 0.5).takeWhile(_ < period)
    offsets.map { o =>
      val (m, k) = gridMean(env, period, o); (o, m, k)
    }.maxBy(_._2)
  }

  /** A tempo estimate, and the all-onset winner's bpm when the kick moved it to a related tempo. */
  case class Estimate(state: BeatState, movedFrom: Option[Double])

  /**
   * Accents or a bass line can make a related tempo win on all the onsets while the kick keeps another: the period of
   * the related tempo the kick clearly prefers to the `winner`, if there is one.
   */
  private def kickPreferred(low: Array[Double], lowMean: Double, winner: Double, minPeriod: Double, maxPeriod: Double): Option[Double] = {
    val lowSpread = math.sqrt(low.map(v => (v - lowMean) * (v - lowMean)).sum / low.length)
    def kickScore(p: Double): Double = {
      val (_, m, k) = bestOffset(low, p)
      (m - lowMean) / math.max(lowSpread, 1e-9) * math.sqrt(k.toDouble)
    }
    val winnerScore = kickScore(winner)
    RelatedRatios
      .map(winner / _)
      .filter(p => p >= minPeriod && p <= maxPeriod)
      .map(p => (p, kickScore(p)))
      .maxByOption(_._2)
      .filter((_, kick) => kick > 0 && kick > KickMargin * winnerScore)
      .map(_._1)
  }

  /**
   * The tempo and how confident it is come from all the onsets, `envelope`. Where the beats fall comes from the low
   * end alone, `bass`: the kick lands on the beat, while hi-hats usually land between beats and can outweigh it.
   */
  def estimate(
    s: TrackerSettings,
    envelope: Vector[Double],
    bass: Vector[Double],
    loudness: Vector[Double],
    now: FiniteDuration,
    previous: Option[BeatState]
  ): Option[Estimate] = {
    val recentLoudness = loudness.takeRight((2 * s.frameRate).toInt)
    val quiet = recentLoudness.isEmpty || recentLoudness.sum / recentLoudness.size < s.silenceRms
    val env = smoothed(envelope)
    val mean = env.sum / env.length
    val spread = math.sqrt(env.map(v => (v - mean) * (v - mean)).sum / env.length)
    if (quiet || spread <= 1e-9) None
    else {

      /**
       * How well a beat grid explains the onsets: how far above average its beats are, weighted by how many hits it
       * covers (so a grid isn't rewarded for skipping every other beat) and by how plausible its tempo is.
       */
      def score(period: Double): Double = {
        val (_, m, k) = bestOffset(env, period)
        (m - mean) / spread * math.sqrt(k.toDouble) * prior(60 * s.frameRate / period)
      }

      val minPeriod = 60 * s.frameRate / s.maxBpm
      val maxPeriod = math.min(env.length / 2.0, 60 * s.frameRate / s.minBpm)
      val candidates = Iterator.iterate(minPeriod)(_ + 0.1).takeWhile(_ <= maxPeriod).toVector
      val winner = candidates.maxBy(score)

      val low = smoothed(bass)
      val lowMean = low.sum / math.max(1, low.length)
      val lowUsable = low.length == env.length && low.exists(_ > lowMean + 1e-9)

      val kickMoved = if (lowUsable) kickPreferred(low, lowMean, winner, minPeriod, maxPeriod) else None
      val period = kickMoved.getOrElse(winner)
      val measuredBpm = 60 * s.frameRate / period
      val bpm = previous match {
        case Some(p) if math.abs(measuredBpm - p.bpm) / p.bpm < TempoTolerance => 0.7 * p.bpm + 0.3 * measuredBpm
        case _ => measuredBpm
      }
      val beatFrames = 60 * s.frameRate / bpm
      val (_, gridLevel, _) = bestOffset(env, beatFrames)
      val confidence = (gridLevel - mean) / spread

      val phaseFrom = if (lowUsable) low else env
      val phaseMean = phaseFrom.sum / phaseFrom.length
      val (bestAt, bestLevel, _) = bestOffset(phaseFrom, beatFrames)
      // Once there's a beat, follow its grid (allowing for a little drift) and only move to another phase once that
      // has been stronger for a while: the beat and the off-beat are often close for a few bars, and flipping between
      // them throws the lights half a beat out.
      val (offset, doubt) = previous.filter(p => math.abs(bpm - p.bpm) / p.bpm < TempoTolerance).fold((bestAt, 0.0)) { p =>
        val sinceBeat = (now - p.beatAt).toNanos.toDouble / p.period.toNanos
        val continued = (sinceBeat - math.floor(sinceBeat)) * p.period.toNanos / s.hopDuration.toNanos
        val (followAt, followLevel) = (-4 to 4).map { step =>
          val o = continued + step * 0.5
          val wrapped = if (o < 0) o + beatFrames else if (o >= beatFrames) o - beatFrames else o
          (wrapped, gridMean(phaseFrom, beatFrames, wrapped)._1)
        }.maxBy(_._2)
        val phaseSpread = math.sqrt(phaseFrom.map(v => (v - phaseMean) * (v - phaseMean)).sum / phaseFrom.length)
        val memory = 1 - math.exp(-(now - p.updatedAt).toNanos / 1e9 / s.phaseMemorySeconds)
        val nextDoubt = p.doubt + ((bestLevel - followLevel) / math.max(phaseSpread, 1e-9) - p.doubt) * memory
        if (nextDoubt > s.phaseSwitch) (bestAt, 0.0) else (followAt, nextDoubt)
      }
      val beatAt = now - (offset * s.hopDuration.toNanos).toLong.nanos
      val number = previous.fold(0L)(p => p.number + math.round((beatAt - p.beatAt).toNanos.toDouble / p.period.toNanos))
      Some(Estimate(BeatState(bpm, beatAt, now, confidence, doubt, number), kickMoved.map(_ => 60 * s.frameRate / winner)))
    }
  }
}

package domain.engine

import beat.{BarAccent, Groove}
import domain.config.PulseSettings

object Pulse {

  /** Envelope level in [0, 1] at `phase` pulses since the start; only the fractional part matters. */
  def level(phase: Double, s: PulseSettings): Double = {
    val p = phase - math.floor(phase)
    val decayStart = s.attack + s.sustain
    if (p < s.attack) p / s.attack
    else if (p < decayStart) 1.0
    else math.pow(1.0 - (p - decayStart) / (1.0 - decayStart), s.decayCurve)
  }

  /**
   * Envelope level `phase` pulses after a pulse lands, timed so the attack comes just before it and the peak lands on
   * it: rising on the beat instead would leave the peak a fifth of a beat late, more on slower songs.
   */
  def onBeat(phase: Double, s: PulseSettings): Double = level(phase + s.attack, s)

  /** The pulse [[onBeat]] is playing `phase` pulses in: the one that lands next while rising, the last one after. */
  def pulseAt(phase: Double, s: PulseSettings): Long = ???

  /**
   * Envelope level `beats` beats into the beat grid for a light following the bar's kick pattern: each sixteenth of
   * the bar gets its own pulse, as strong as the groove's weight there and timed like [[onBeat]], so its peak lands on
   * the sixteenth. A groove with a full kick on every beat gives exactly the beat pulse.
   */
  def rhythm(groove: Vector[Double], beats: Double, s: PulseSettings): Double = {
    val bar = Groove.BeatsPerBar.toDouble
    val inBar = beats - math.floor(beats / bar) * bar
    groove.indices.foldLeft(0.0) { (strongest, step) =>
      val rising = inBar - step.toDouble / Groove.StepsPerBeat + s.attack
      val phase = rising - math.floor(rising / bar) * bar
      if (phase < 1) math.max(strongest, groove(step) * level(phase, s)) else strongest
    }
  }

  /** [[rhythm]], dimmed away from the downbeat by [[accentFactor]]. */
  def rhythm(groove: Vector[Double], beats: Double, s: PulseSettings, accent: BarAccent, strength: Double): Double =
    rhythm(groove, beats, s) * accentFactor(groove, beats, accent, strength)

  /**
   * How much of the rhythm envelope plays `beats` beats into the grid: all of it while the accent is off at the beat,
   * or while `beats` is nearer the first sixteenth of a downbeat than any other sixteenth with a groove weight above 0,
   * the groove repeating bar on bar; otherwise `1 - strength`. So the downbeat's hit peaks as it would without the
   * accent, and every other hit, with whatever is still fading under it, at `1 - strength` of that.
   */
  def accentFactor(groove: Vector[Double], beats: Double, accent: BarAccent, strength: Double): Double = ???

  /**
   * Brightness multiplier for an envelope level: `restLevel` at rest, `restLevel + peakBoost` at the peak, all scaled
   * by the music's `intensity` (1 when the show isn't reacting to live audio).
   */
  def brightness(level: Double, s: PulseSettings, intensity: Double = 1.0): Double = (s.restLevel + s.peakBoost * level) * intensity
}

package domain.engine

import beat.{AudioReading, BarAccent}
import domain.config.{PulseSettings, ReactiveSettings, SwellSettings}
import scala.concurrent.duration.FiniteDuration

/**
 * How the music shapes the show at one moment: an overall brightness, a turn of the palette's hue, a white flash
 * across every light after a big hit, and a twinkle on one light after a treble onset. With live audio, each light
 * also has a role: `rhythm` is where the show is in the bar's kick pattern, `paletteShift` how many palette colours
 * the colour lights have moved along the palette, and `swell` how they swell. `rhythmIntensity`, when there is one,
 * is the rhythm lights' brightness in place of `intensity`. `accent` is the beat that starts the bar, if the harmony
 * shows one, and `accentStrength` how far the rest of the bar's rhythm hits and pulses are dimmed.
 */
case class Effects(
  intensity: Double = 1.0,
  hueShift: Int = 0,
  flash: Double = 0.0,
  sparkle: Option[Sparkle] = None,
  roles: Vector[LightRole] = Vector.empty,
  rhythm: Option[Rhythm] = None,
  paletteShift: Double = 0.0,
  swell: SwellSettings = SwellSettings(),
  rhythmIntensity: Option[Double] = None,
  accent: BarAccent = BarAccent.Off,
  accentStrength: Double = 0.0
) {

  /** The given light's role; without live audio every light pulses. */
  def roleOf(light: Int): LightRole = roles.lift(light).getOrElse(LightRole.Pulse)

  /** How far the given light is pushed towards white. */
  def whiteFor(light: Int): Double =
    math.min(1.0, flash + sparkle.filter(_.light == light).fold(0.0)(_.amount))

  /** A rhythm light's brightness multiplier `pulses` pulses in: the kick pattern, or every pulse until there's a live beat. */
  def rhythmLight(pulses: Double, settings: PulseSettings): Double =
    Pulse.brightness(
      rhythm.fold(Pulse.onBeat(pulses, settings))(r => Pulse.rhythm(r.groove, r.beats, settings, accent, accentStrength)),
      settings,
      rhythmIntensity.getOrElse(intensity)
    )

  /**
   * A pulse light's brightness multiplier `pulses` pulses in, peaking `lag` pulses after light 0. Which beat of the bar
   * the pulse is on comes from the count since locking on (`rhythm.beats - lag`), since `pulses` starts again with each
   * estimate of the beat; off the downbeat its peak boost is scaled by `1 - accentStrength`.
   */
  def pulseLight(lag: Double, pulses: Double, settings: PulseSettings): Double = ???

  /** These effects when the show pulses once every `beatsPerPulse` beats: the accent only plays when every beat pulses. */
  def forPulsesOf(beatsPerPulse: Double): Effects = ???
}

object Effects {

  /** No reaction: the pulse exactly as configured. */
  val neutral: Effects = Effects()

  /** Spreads successive sparkles over the lights, so they don't just walk along the zone. */
  private val Scatter = 7919L

  def at(now: FiniteDuration, reading: AudioReading, lights: Int, settings: ReactiveSettings): Effects = {
    def fading(since: FiniteDuration, decayMs: Long): Double = {
      val elapsedMs = (now - since).toMillis.toDouble
      if (elapsedMs < 0) 1.0 else math.exp(-elapsedMs / decayMs)
    }
    val intensity = math.max(settings.quietest, math.min(settings.loudest, reading.energy))
    val hueShift = math.round(settings.colourShift * math.max(-1.0, math.min(1.0, reading.treble - 1.0))).toInt
    val flash = reading.hit.fold(0.0)(hit => settings.flash * hit.strength * fading(hit.at, settings.flashDecayMs))
    val roles = LightRole.assign(settings.roles, lights)
    val twinkling = roles.indices.filter(roles(_) != LightRole.Rhythm)
    val sparkle = reading.sparkle
      .filter(_ => twinkling.nonEmpty)
      .map(s =>
        Sparkle(twinkling(Math.floorMod(reading.sparkles * Scatter, twinkling.size.toLong).toInt),
          settings.sparkle * s.strength * fading(s.at, settings.sparkleDecayMs))
      )
      .filter(_.amount > 0.005)
    val rhythm = reading.beat.filter(_ => reading.groove.nonEmpty).map(b => Rhythm(reading.groove, b.countAt(now)))
    val rhythmIntensity = reading.rhythmEnergy.map(e => math.max(settings.quietest, math.min(settings.loudest, e)))
    Effects(intensity, hueShift, if (flash > 0.005) flash else 0.0, sparkle, roles, rhythm, reading.pitch * settings.colourReach,
      settings.colourSwell, rhythmIntensity, reading.accent, settings.downbeatAccent)
  }
}

import cats.effect.*
import cats.effect.syntax.all.*
import cats.syntax.all.*
import beat.{AudioReading, BarAccent, BeatState, TempoNews}
import client.{AlbumCovers, CoverError, SpotifyClient, SpotifyTlsFailure}
import fs2.Stream
import domain.config.{AppConfig, LightShowConfig, PulseSettings}
import domain.engine.{Effects, LightRole, LocalPlayback, Palette, PaletteType, Pulse, RGB, Renderer}
import domain.hue.*
import domain.spotify.types.TrackId
import fs2.concurrent.SignallingRef
import org.typelevel.log4cats.SelfAwareStructuredLogger
import org.typelevel.log4cats.slf4j.Slf4jLogger
import scala.concurrent.duration.*
import scala.util.Random
import scala.util.control.NonFatal
import settings.LiveSettings

/**
 * The track's tempo from Spotify, if it gave one, and the palette, settings and lights the show plays it with. `base` is
 * the colour the palette was built from, kept so a new palette type can be built from the same colour.
 */
case class TrackShow(tempo: Option[Double], palette: Palette, settings: LightShowConfig, zone: Zone, base: RGB) {
  def bpm: Double = tempo.getOrElse(settings.defaultBpm) / settings.beatsPerPulse
}

class SyncEngine[F[_]: Async] private (
  config: AppConfig,
  live: LiveSettings[F],
  zone: Zone,
  spotify: SpotifyClient[F],
  lights: Lights[F],
  current: Ref[F, Option[(TrackId, TrackShow)]],
  random: Random,
  audio: Stream[F, AudioReading],
  covers: AlbumCovers[F]
):

  private val logger: SelfAwareStructuredLogger[F] = Slf4jLogger.getLogger[F]

  private def randomBase: F[RGB] =
    Async[F].delay(RGB.random(using random))

  private def paletteFrom(base: RGB, paletteType: PaletteType): F[Palette] =
    Async[F].fromOption(Palette.from(base, paletteType), new IllegalStateException(s"Couldn't make a $paletteType palette"))

  private def coverFailure(trackId: TrackId, url: String, err: Throwable): F[Unit] = {
    val detail = err match {
      case e: CoverError =>
        val extra = e match {
          case CoverError.Refused(_, status) => Map("status" -> status.code.toString)
          case CoverError.TimedOut(_, after) => Map("waited_ms" -> after.toMillis.toString)
          case _ => Map.empty[String, String]
        }
        extra + ("reason" -> e.reason)
      case _ => Map("reason" -> "failed")
    }
    logger.warn(Map("track_id" -> trackId.toString, "cover_url" -> url) ++ detail)(
      s"Couldn't take the colours from the album cover for $trackId, using a random palette: ${err.getMessage}"
    )
  }

  private def tempoFor(trackId: TrackId): F[Option[Double]] =
    spotify.getTempo(trackId).handleErrorWith { err =>
      (err match {
        case _: SpotifyTlsFailure => logger.error(s"Couldn't fetch the tempo for $trackId: $err")
        case _ => logger.warn(s"Couldn't fetch the tempo for $trackId: $err")
      }) *> Async[F].pure(None)
    }

  private def baseDescription(fromCover: Option[RGB], base: RGB): String =
    fromCover.fold(s"random base ${base.hex}")(_ => s"base ${base.hex} from the album cover")

  /** The cover's base colour, if the setting is on and the cover arrives in time and has one. Any failure is logged and gives None. */
  private def coverBase(trackId: TrackId, cover: Option[String], settings: LightShowConfig): F[Option[RGB]] =
    cover.filter(_ => settings.albumCoverColours).fold(Async[F].pure(Option.empty[RGB])) { url =>
      covers.baseColour(url).start.flatMap { fiber =>
        fiber.joinWithNever
          .onCancel(fiber.cancel.start.void)
          .timeoutTo(SyncEngine.CoverWait, Async[F].raiseError[Option[RGB]](CoverError.TimedOut(url, SyncEngine.CoverWait)))
      }.handleErrorWith { case NonFatal(err) => coverFailure(trackId, url, err).as(None) }
    }

  /** The lights to play `settings` on: the area they name, or else the ones `before` played on (or the first zone). */
  private def zoneFor(settings: LightShowConfig, before: Option[TrackShow]): F[Zone] = {
    val fallback = before.fold(zone)(_.zone)
    settings.area match {
      case None => Async[F].pure(fallback)
      case Some(name) if before.exists(_.settings.area.contains(name)) => Async[F].pure(fallback)
      case Some(name) =>
        lights.zone(name).attempt.flatMap {
          case Right(Some(found)) => logger.info(s"Playing on the $name area").as(found)
          case Right(None) => logger.warn(s"There's no $name area on the bridge; staying where the show is").as(fallback)
          case Left(err) => logger.warn(s"Couldn't read the $name area from the bridge, staying where the show is: $err").as(fallback)
        }
    }
  }

  /**
   * The show for a track. A new track takes up the latest settings, its area's lights and a new palette; the show
   * then stays the same until the track changes, so changes from the settings page wait for the next song.
   */
  def showFor(trackId: TrackId, cover: Option[String] = None): F[TrackShow] =
    current.get.flatMap {
      case Some((playing, show)) if playing == trackId => Async[F].pure(show)
      case before =>
        for {
          settings <- live.startSong
          (tempo, fromCover) <- Async[F].both(tempoFor(trackId), coverBase(trackId, cover, settings))
          base <- fromCover.fold(randomBase)(Async[F].pure)
          palette <- paletteFrom(base, settings.palette)
          lit <- zoneFor(settings, before.map(_._2))
          created = TrackShow(tempo, palette, settings, lit, base)
          _ <- current.set(Some(trackId -> created))
          source = tempo.fold(s"default ${settings.defaultBpm} BPM")(t => s"track tempo $t BPM")
          _ <- logger.info(
            s"New show for $trackId: pulsing at ${created.bpm} BPM ($source), palette ${settings.palette}, ${baseDescription(fromCover, base)}:\n${palette.show}"
          )
        } yield created
    }

  /** The palette of the song playing now, if one has started. */
  def palette: F[Option[Palette]] = current.get.map(_.map(_._2.palette))

  /**
   * Takes up the latest settings now rather than at the next song, moving to another area if they name one. The palette
   * only changes if its type did, and then it's built from the colour the song started with.
   */
  def applyNow: F[Unit] =
    for {
      settings <- live.startSong
      playing <- current.get
      _ <- playing.traverse_ { (trackId, show) =>
        val palette = if (show.settings.palette == settings.palette) Async[F].pure(show.palette) else paletteFrom(show.base, settings.palette)
        (palette, zoneFor(settings, Some(show))).flatMapN((p, lit) =>
          current.set(Some(trackId -> show.copy(palette = p, settings = settings, zone = lit)))
        )
      }
    } yield ()

  /**
   * Keeps `audioRef` up to date with what the music is doing, logging when the beat locks on, is lost or changes
   * tempo, and when the downbeat accent switches on, moves or switches off. On failure it clears the reading, so the
   * show carries on with Spotify timing and no audio effects.
   */
  private def followAudio(audioRef: Ref[F, Option[AudioReading]]): Stream[F, Nothing] =
    audio
      .evalMapAccumulate((Option.empty[Double], BarAccent.Off)) { (logged, reading) =>
        val (tempoLogged, accentLogged) = logged
        val (remembered, news) = SyncEngine.beatNews(tempoLogged, reading.beat)
        val accentLine = SyncEngine.accentNews(accentLogged, reading.accent)
        ((news.toList ++ reading.news.map(SyncEngine.tempoNewsLine)).traverse_(logger.info(_)) *>
          accentLine.traverse_((fields, line) => logger.info(fields)(line)) *>
          audioRef.set(Some(reading))).as(((remembered, reading.accent), ()))
      }
      .drain
      .handleErrorWith { err =>
        Stream.exec(audioRef.set(None) *> logger.warn(s"Listening stopped, using Spotify timing instead: ${err.getMessage}"))
      }

  def run: Stream[F, Frame] =
    Stream.eval((SignallingRef[F, Option[LocalPlayback]](None), Ref.of[F, Option[AudioReading]](None)).tupled).flatMap { (stateRef, audioRef) =>
      val poller = Stream.awakeEvery[F](config.pollingIntervalMs.millis)
        .evalMap { _ =>
          spotify.getPlaybackState.handleErrorWith { err =>
            logger.error(s"Spotify Poll Failed: $err") *> Async[F].pure(None)
          }
        }
        .evalMap(state => Clock[F].realTimeInstant.map(now => state.map(LocalPlayback(_, now))))
        .evalMap(stateRef.set)

      val renderer = Stream.awakeEvery[F](config.lightShow.frameIntervalMs.millis)
        .evalMap(_ => stateRef.get)
        .evalMapAccumulate(Renderer.initial) { (rendered, playback) =>
          playback.filter(_.state.isPlaying).fold(
            (Clock[F].monotonic, live.applied, current.get).mapN { (now, show, playing) =>
              Renderer.paused(rendered, now, playing.fold(zone)(_._2.zone), show.pause)
            }
          )(local => playingFrame(local, audioRef).map(Renderer.playing))
        }
        .map(_._2)

      renderer.merge(poller.drain).merge(followAudio(audioRef))
        .zipWithIndex
        .map((frame, i) => frame.copy(sequence = (i % 256).toInt))
    }

  /**
   * The frame for the current moment of a playing track. With a live beat, pulses follow it; otherwise they follow
   * Spotify's playback position at the track's tempo. With live audio, the effects follow the music too.
   */
  private def playingFrame(local: LocalPlayback, audioRef: Ref[F, Option[AudioReading]]): F[Frame] =
    for {
      track <- showFor(local.state.trackId, local.state.albumCoverUrl)
      show = track.settings
      reading <- audioRef.get
      monotonic <- Clock[F].monotonic
      now <- Clock[F].realTimeInstant
      heardAt = monotonic + show.audio.offsetMs.millis
      pulses = reading.flatMap(_.beat).fold {
        val latencyMs = java.time.Duration.between(local.receivedAt, now).toMillis
        SyncEngine.pulsesAt(local.state.progress.toMillis + latencyMs + show.syncOffsetMs, track.bpm)
      }(b => b.beatsAt(heardAt) / show.beatsPerPulse)
      effects = reading
        .filter(_ => show.reactive.enabled)
        .fold(Effects.neutral)(r => Effects.at(heardAt, r, track.zone.channels.size, show.reactive).forPulsesOf(show.beatsPerPulse))
    } yield SyncEngine.pulseFrame(track.zone, track.palette, pulses, show.pulse, effects)

object SyncEngine:

  def make[F[_]: Async](
    config: AppConfig,
    live: LiveSettings[F],
    spotify: SpotifyClient[F],
    zone: Zone,
    lights: Lights[F],
    random: Random = new Random(),
    audio: Stream[F, AudioReading] = Stream.empty,
    covers: Option[AlbumCovers[F]] = None
  ): F[SyncEngine[F]] =
    Ref.of[F, Option[(TrackId, TrackShow)]](None).map(
      new SyncEngine[F](config, live, zone, spotify, lights, _, random, audio, covers.getOrElse(AlbumCovers.none[F]))
    )

  /** The longest a song's first frame waits for its album cover. */
  val CoverWait: FiniteDuration = 1.second

  /** How far the tempo has to move from the last one logged before it's logged again. */
  private val TempoChangeToLog: Double = 0.03

  /**
   * What to log about the beat, given the tempo logged last and the latest beat: that it locked on, that it was lost,
   * or that the tempo moved by more than `TempoChangeToLog`. Returns the tempo to remember and the message, if any.
   */
  def beatNews(logged: Option[Double], beat: Option[BeatState]): (Option[Double], Option[String]) =
    (logged, beat) match {
      case (None, Some(b)) => (Some(b.bpm), Some(f"Locked onto the beat at ${b.bpm}%.1f BPM (confidence ${b.confidence}%.1f)"))
      case (Some(_), None) => (None, Some("Lost the beat; using Spotify timing until it's back"))
      case (Some(was), Some(b)) if math.abs(b.bpm - was) / was > TempoChangeToLog =>
        (Some(b.bpm), Some(f"Tempo changed from $was%.1f to ${b.bpm}%.1f BPM (confidence ${b.confidence}%.1f)"))
      case _ => (logged, None)
    }

  /**
   * What to log about the downbeat accent, given the accent seen last and the latest: that it switched on, moved or
   * switched off, with its fields, beats numbered 1 to 4. None when its slot hasn't changed.
   */
  def accentNews(logged: BarAccent, accent: BarAccent): Option[(Map[String, String], String)] = ???

  /** The log line for a tempo decision: both tempos and the ratio of the new one to the old. */
  def tempoNewsLine(news: TempoNews): String =
    news match {
      case TempoNews.KickMoved(from, to) =>
        f"The kick fits $to%.1f BPM better than $from%.1f BPM (ratio ${to / from}%.2f); using $to%.1f BPM"
      case TempoNews.FollowedRelated(from, to) =>
        f"Followed a related tempo from $from%.1f to $to%.1f BPM (ratio ${to / from}%.2f) once it had held"
    }

  /** Pulses elapsed at a playback position, pulsing at `bpm`. */
  def pulsesAt(positionMs: Long, bpm: Double): Double = positionMs * bpm / 60000.0

  private val White: RGB = RGB.safe(255, 255, 255).get

  /**
   * One frame of the show for every channel in the zone, `pulses` pulses into the music. Light i takes palette colour
   * i, and what it does depends on its role:
   *  - a pulse light peaks `stagger` of a pulse after light i - 1 (light 0 on every whole pulse), so the pulse travels
   *    across the zone, and its hue turns with the treble;
   *  - a rhythm light pulses with the bar's kick pattern, or on every pulse until there's a live beat;
   *  - a colour light swells once every `swell.beats` beats, peaking on the beat, and moves along the palette as the
   *    music goes higher or lower.
   * The effects scale the brightness, dim the rest of the bar around the downbeat on pulse and rhythm lights, and push
   * lights towards white for flashes and sparkles.
   */
  def pulseFrame(zone: Zone, palette: Palette, pulses: Double, settings: PulseSettings, effects: Effects = Effects.neutral): Frame = {
    val updates = zone.channels.zipWithIndex.map { (channel, i) =>
      val (brightness, colour) = effects.roleOf(i) match {
        case LightRole.Pulse =>
          val own = palette.getColor(i)
          (effects.pulseLight(i * settings.stagger, pulses, settings), if (effects.hueShift == 0) own else own.rotateHue(effects.hueShift))
        case LightRole.Rhythm =>
          (effects.rhythmLight(pulses, settings), palette.getColor(i))
        case LightRole.Colour =>
          // Counted along the beat grid when there's a live beat, so every other beat stays the same beat as the tracker re-estimates.
          val beats = effects.rhythm.fold(pulses)(_.beats)
          val shape = effects.swell.shape
          (Pulse.brightness(Pulse.onBeat(beats / effects.swell.beats, shape), shape, effects.intensity), palette.along(i, effects.paletteShift))
      }
      val lit = colour.scaleBrightness(brightness)
      val white = effects.whiteFor(i)
      LightUpdate(channel, if (white <= 0) lit else lit.mix(White, white))
    }
    Frame(zone.id, updates)
  }
